def list_dir(path, depth=0, maxdepth=2):
    try:
        d=fs.open_dir(path=path)
    except Exception as e:
        print('ERR', path, e)
        return
    for e in d:
        try:
            name=e.info.name.name.decode('utf-8','ignore')
        except:
            continue
        if name in ['.','..']:
            continue
        meta=e.info.meta
        typ=meta.type if meta else None
        size=meta.size if meta else None
        mtime=meta.mtime if meta else None
        print('  '*depth + f'{path}/{name} type={typ} size={size} mtime={mtime}')
        if typ==2 and depth<maxdepth:
            list_dir(path+'/'+name, depth+1, maxdepth)

