want={b'SAM',b'SYSTEM',b'SOFTWARE',b'SECURITY',b'NTUSER.DAT',b'UsrClass.dat',b'UsrClass.dat.LOG1',b'UsrClass.dat.LOG2'}
for dirpath, dirent in [('/',fs.open_dir('/'))]:
    pass
# recursive walk limited by names of interest
stack=['/']
seen=0
while stack:
    p=stack.pop()
    try:
        d=fs.open_dir(p)
    except Exception:
        continue
    for e in d:
        name=e.info.name.name
        if name in (b'.',b'..'):
            continue
        meta=e.info.meta
        full=(p.rstrip('/')+'/'+name.decode('utf-8','replace')) if p!='/' else '/'+name.decode('utf-8','replace')
        if meta and meta.type==pytsk3.TSK_FS_META_TYPE_DIR:
