from regipy.registry import RegistryHive
h=RegistryHive('work/extracted/sd8ee03/hives/SOFTWARE')
# traverse to uninstall keys in both views
roots=[('SOFTWARE', ['Microsoft','Windows','CurrentVersion','Uninstall']),
       ('SOFTWARE', ['Wow6432Node','Microsoft','Windows','CurrentVersion','Uninstall'])]
for start, path in roots:
    key=h.root.get_subkey(start)
    ok=True
    for p in path:
        try:
            key=key.get_subkey(p)
        except Exception:
            ok=False
            break
    if not ok:
        continue
    print('PATH', '/'.join([start]+path))
    for s in key.iter_subkeys():
        vals={v.name:v.value for v in s.iter_values()}
        dn=vals.get('DisplayName')
        if dn:
            print(' -', dn)
PY

