import pytsk3, os, re
img='inputs/s4a-challenge4'; off=2048*512
fs=pytsk3.FS_Info(pytsk3.Img_Info(img), offset=off)
pat=re.compile(r'.*\.(asp|aspx|php|jsp|cgi|exe|bat|cmd|vbs|ps1|txt|zip|rar|7z|dll|lnk|dat|log|sql|config|xml)$', re.I)
found=[]

def walk(path, depth=0):
    try:
        d=fs.open_dir(path=path)
    except Exception:
        return
    for e in d:
        try:
            name=e.info.name.name.decode('utf-8','ignore')
        except:
            continue
        if name in ['.','..']:
            continue
        meta=e.info.meta
        if meta and pat.match(name):
            found.append((path+'/'+name, meta.type, meta.size, meta.mtime, meta.crtime, meta.atime, meta.ctime))
        if meta and meta.type==2 and depth<8:
            walk(path+'/'+name, depth+1)

walk('/')
for row in sorted(found)[:1000]:
    print('|'.join(str(x) for x in row))
print('COUNT', len(found))
PY

